code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    base = max(counts, key=counts.get)
    # Edge colors are the non-background colors occupying contiguous border runs.
    edge_counts = {}
    for r in range(h):
        for c in range(w):
            if r in (0, h-1) or c in (0, w-1):
                v = grid[r][c]
                if v != base:
                    edge_counts[v] = edge_counts.get(v, 0) + 1
    edge = max(edge_counts, key=edge_counts.get)
    marker_counts = {v:n for v,n in counts.items() if v not in (base, edge)}
    marker = min(marker_counts, key=marker_counts.get)
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    for r,c in points:
        out[r][c] = 4
        candidates = []
        # Rays go toward an edge-color cell in the same row or column.
        for cc in range(c-1, -1, -1):
            if grid[r][cc] == edge:
                candidates.append((c-cc, 0, r, cc, 0, -1)); break
        for cc in range(c+1, w):
            if grid[r][cc] == edge:
                candidates.append((cc-c, 0, r, cc, 0, 1)); break
        for rr in range(r-1, -1, -1):
            if grid[rr][c] == edge:
                candidates.append((r-rr, 1, rr, c, -1, 0)); break
        for rr in range(r+1, h):
            if grid[rr][c] == edge:
                candidates.append((rr-r, 1, rr, c, 1, 0)); break
        if not candidates:
            continue
        _, _, er, ec, dr, dc = min(candidates)
        rr, cc = r + dr, c + dc
        while (rr,cc) != (er,ec):
            if out[rr][cc] != edge:
                out[rr][cc] = marker
            rr += dr; cc += dc
    return out
'''
